import { gameGroups,clickingGames,webcamGames,gameKey,gameTitle,gameStatus,flowScore,nextGame,flowProgress,readWebcamSkips,setWebcamSkip,forgetWebcamSkips,type FlowGame,type FlowProgress } from '@/lib/flow';
