const icons={search:ScanSearch,memory:Brain,spatial:Shapes};
const descriptions={search:'Find a target among similar shapes.',memory:'Remember a pattern, then find its match.',spatial:'Compare positions and match a pattern.'};
const sources=[['Understanding convergence insufficiency','National Eye Institute','https://www.nei.nih.gov/eye-health-information/eye-conditions-and-diseases/convergence-insufficiency'],['What treatment trials actually show','CITT · randomized clinical trial, ages 9–17','https://pmc.ncbi.nlm.nih.gov/articles/PMC2779032/'],['Vision treatment and reading outcomes','National Eye Institute','https://www.nei.nih.gov/research-and-training/research-news/treatment-common-vision-disorder-does-not-improve-childrens-reading-skills'],['Double vision: when to seek help','NHS · reviewed January 2024','https://www.nhs.uk/symptoms/double-vision/'],['Sudden vision changes','National Eye Institute · retinal detachment','https://www.nei.nih.gov/eye-health-information/eye-conditions-and-diseases/retinal-detachment'],['Vision therapy: evidence and limitations','American Association for Pediatric Ophthalmology and Strabismus','https://www.aapos.org/glossary/vision-therapy']];
const date=(s:string)=>new Date(s).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});
function Pattern({cells,large=false}:{cells:number[],large?:boolean}){return <span className={'pattern '+(large?'large':'')} aria-hidden="true">{Array.from({length:9},(_,i)=><i key={i} className={cells.includes(i)?'filled':''}/>)}</span>}
const checkGroups:[string,number[]][]=[['Eyes and comfort',[0,1,2,5]],['Reading and everyday tasks',[3,6,7,8,9,4]]];
function ExamGuidance({onSheet}:{onSheet?:()=>void}){return <div className="exam-guidance"><h4>What to ask for</h4><ul>{examGuidance.map(g=><li key={g}>{g}</li>)}</ul>{onSheet&&<Button variant="outline" onClick={onSheet}><ClipboardList size={16}/>Appointment sheet</Button>}</div>}
function exportFile(data:Data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='little-lens-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
export default function Home(){const [data,setData]=useState<Data>(empty),[ready,setReady]=useState(false),[error,setError]=useState(''),[active,setActive]=useState(''),[tab,setTab]=useState('home'),[dialog,setDialog]=useState<'profile'|'check'|'settings'|null>(null),[run,setRun]=useState<Attempt|null>(null),[expandedRun,setExpandedRun]=useState<ExtendedAttempt|null>(null),[suiteRun,setSuiteRun]=useState<SuiteRecord|null>(null),[level,setLevel]=useState(1),[worksheet,setWorksheet]=useState<Kind|null>(null),[busy,setBusy]=useState(false),[notice,setNotice]=useState(''),[sheet,setSheet]=useState(false),[flowMode,setFlowMode]=useState<'games'|'webcam'|null>(null),[upNext,setUpNext]=useState(false),[skipped,setSkipped]=useState<Set<string>>(new Set()),[webcamSkips,setWebcamSkips]=useState<string[]>(()=>readWebcamSkips());const file=useRef<HTMLInputElement>(null);const p=data.profiles.find(p=>p.id===active);const attempts=data.attempts.filter(a=>a.profileId===active).sort((a,b)=>a.date.localeCompare(b.date));const checks=data.checks.filter(c=>c.profileId===active).sort((a,b)=>a.date.localeCompare(b.date));const latest=checks.at(-1);const webcamSkipped=!!p&&webcamSkips.includes(p.id);const progress=flowProgress(data,p?.id,webcamSkipped);const score=p?flowScore(data,p.id):{correct:0,total:0,percent:0};
function setWebcamSkipped(skip:boolean){if(p)setWebcamSkips(setWebcamSkip(p.id,skip));}
function play(g:FlowGame){if(g.family==='original')void start(g.kind,'assessment');else if(g.family==='extended')void startExpanded(g.kind,'assessment');else void startSuite(g.kind);}
function playStep(mode:'games'|'webcam'){setFlowMode(mode);setSkipped(new Set());const g=p&&nextGame(data,p.id,mode==='games'?clickingGames:webcamGames);if(g)play(g);else setUpNext(true);}
function gameClosed(message:string){if(flowMode)setUpNext(true);else setNotice(message);}
useEffect(()=>{loadData().then(d=>{setData(d);setActive(d.profiles[0]?.id||'');setReady(true);}).catch(()=>{setError('Local storage could not be opened. Your existing data has not been replaced. Enable browser storage, close other tabs, and reload.');});},[]);
async function persist(next:Data){setBusy(true);try{await saveData(next,data);setData(next);setError('');return true;}catch(e){setError(e instanceof Error&&e.message.startsWith('Data changed')?e.message:'Your changes could not be saved on this device. Free browser storage and try again. Export your existing data before clearing anything.');return false;}finally{setBusy(false);}}
async function startSuite(kind:SuiteKind){if(!p){setDialog('profile');return;}const r=newSuiteRecord(p.id,kind);if(await persist({...data,suite:[...data.suite,r]}))setSuiteRun(r);}
async function saveSuite(r:SuiteRecord){return persist({...data,suite:upsertSuiteRecord(data.suite,r)});}
async function startExpanded(kind:ExtendedKind,mode:'assessment'|'practice'){if(!p){setDialog('profile');return;}const a=makeExtendedAttempt(p.id,kind,mode,level,{width:window.innerWidth,height:window.innerHeight,pixelRatio:window.devicePixelRatio},'');if(await persist({...data,extended:[...data.extended,a]}))setExpandedRun(a);}
async function saveExpanded(a:ExtendedAttempt){return persist({...data,extended:data.extended.map(x=>x.id===a.id?a:x)});}
async function start(kind:Kind,mode:'assessment'|'practice'){if(!p){setDialog('profile');return;}const a:Attempt={id:crypto.randomUUID(),profileId:p.id,date:new Date().toISOString(),kind,mode,version:attemptVersion,difficulty:mode==='assessment'?2:level,input:'unknown',status:'incomplete',correct:0,answered:0,total:6,seconds:0};if(await persist({...data,attempts:[...data.attempts,a]}))setRun(a);}
async function finish(a:Attempt){if(await persist({...data,attempts:data.attempts.map(x=>x.id===a.id?a:x)})){setRun(null);gameClosed(a.status==='complete'?`${labels[a.kind]} saved: ${a.correct} of 6 correct. Take a break before continuing.`:'Activity stopped. This incomplete attempt is excluded from comparisons.');}}
async function importBackup(f?:File){if(!f)return;try{if(f.size>50_000_000)throw Error();const next=backupSchema.parse(JSON.parse(await f.text()));if(!confirm('Replace all local profiles and history with this backup? Export your current data first if you want to keep it.'))return;if(await persist(next)){setActive(next.profiles[0]?.id||'');setNotice('Backup imported successfully.');}}catch{setError('This file is not a valid Little Lens version 1, 2, or 3 backup, or exceeds 50 MB. No data was changed.');}finally{if(file.current)file.current.value='';}}
return <><FlowBar progress={progress} score={score} name={p?.nickname} onStep={step=>{setTab('home');setTimeout(()=>document.getElementById(`step-${step}`)?.scrollIntoView({behavior:'smooth',block:'start'}),0);}}/><header className="topbar"><a href="./" className="brand"><span className="brand-icon"><Eye size={25}/></span>little lens<span className="brand-label">VISUAL SKILLS</span></a><div className="header-tools"><span className="privacy"><ShieldCheck size={16}/>Only on your device</span><Button variant="outline" onClick={()=>setDialog('settings')} aria-label="Profile and data settings"><Settings2 size={18}/><span>Profile settings</span></Button></div></header><main>
{error&&<div role="alert" className="alert">{error}</div>}{notice&&<div role="status" className="notice">{notice}<button onClick={()=>setNotice('')} aria-label="Dismiss notification">×</button></div>}
<Tabs value={tab} onValueChange={setTab}><TabsList className="main-tabs"><TabsTrigger value="home"><ListChecks/>Home</TabsTrigger><TabsTrigger value="progress"><ChartNoAxesCombined/>Results</TabsTrigger><TabsTrigger value="practice"><Play/>Practice</TabsTrigger><TabsTrigger value="evidence"><BookOpen/>Evidence</TabsTrigger></TabsList>
<TabsContent value="home"><div className="flow">
<FlowStep n={1} id="step-1" title="Profile" icon={<UserRound/>} state={progress.step===1?'current':'done'} summary={p?`Playing as ${p.nickname} · age ${p.age}`:undefined}>
{data.profiles.length?<div className="profile-picker"><label htmlFor="profile-select">Who is playing?</label><div><select id="profile-select" value={active} onChange={e=>{setActive(e.target.value);setFlowMode(null);}} disabled={!ready||busy}><option value="">Choose a profile</option>{data.profiles.map(p=><option key={p.id} value={p.id}>{p.nickname} · age {p.age}</option>)}</select><Button variant="outline" disabled={!ready||busy} onClick={()=>setDialog('profile')}><Plus size={18}/>Add profile</Button></div></div>:<><p>Create a profile with a nickname to save games and answers on this device. No registration; nothing is uploaded.</p><Button disabled={!ready||busy} onClick={()=>setDialog('profile')}>Create a profile<ArrowRight size={18}/></Button></>}
</FlowStep>
<FlowStep n={2} id="step-2" title="Games" icon={<Gamepad2/>} state={progress.step<2?'upcoming':progress.step===2?'current':'done'} summary={`${progress.games} of ${clickingGames.length} played${score.total?` · ${score.correct}/${score.total} correct`:''}`}>
<p>{clickingGames.length} clicking games for visual search, memory, spatial skills, and attention. Each takes a few minutes; progress is saved after every game, so you can stop and come back. Wear glasses as usual, and stop if eyes feel sore, blurry, or double.</p>
<StepActions mobile="Use a laptop or tablet (at least 700 pixels wide) to play.">{progress.games<clickingGames.length?<Button disabled={!ready||busy||!p} onClick={()=>playStep('games')}><Play size={16}/>{progress.games?'Play next game':'Play all games'}</Button>:<Button variant="outline" disabled={!p} onClick={()=>document.getElementById('step-3')?.scrollIntoView({behavior:'smooth'})}>All games played · Continue to step 3<ArrowRight size={16}/></Button>}</StepActions>
{gameGroups.map(group=><section className="game-group" key={group.title}><h4>{group.title}</h4><ul className="game-list">{group.games.map(g=><GameRow key={gameKey(g)} game={g} status={p?gameStatus(data,p.id,g):{played:false}} disabled={!ready||busy||!p} onPlay={()=>{setFlowMode(null);play(g);}}/>)}</ul></section>)}
</FlowStep>
<FlowStep n={3} id="step-3" title="Webcam games" icon={<Camera/>} state={progress.step<3?'upcoming':progress.step===3?'current':'done'} summary={webcamSkipped?'Skipped':`${progress.webcam} of ${webcamGames.length} played`}>
<p>Experimental games that estimate where you look, using your camera on this device. Nothing is recorded or uploaded. Each starts with a short calibration. Results describe the measurement only; if the camera can't measure well, the game says so. No camera? Skip this step.</p>
<StepActions mobile="Use a laptop or tablet with a camera to play.">{progress.webcam<webcamGames.length&&!webcamSkipped&&<Button disabled={!ready||busy||!p} onClick={()=>playStep('webcam')}><Camera size={16}/>{progress.webcam?'Play next webcam game':'Play webcam games'}</Button>}<Button variant="outline" disabled={!p} onClick={()=>setWebcamSkipped(!webcamSkipped)}>{webcamSkipped?'Undo skip':<><SkipForward size={16}/>Skip webcam games</>}</Button></StepActions>
<ul className="game-list">{webcamGames.map(g=><GameRow key={gameKey(g)} game={g} status={p?gameStatus(data,p.id,g):{played:false}} disabled={!ready||busy||!p} onPlay={()=>{setFlowMode(null);play(g);}}/>)}</ul>
</FlowStep>
<FlowStep n={4} id="step-4" title="Check-in" icon={<ClipboardList/>} state={progress.step<4&&!latest?'upcoming':latest?'done':'current'} summary={latest?`Answered ${date(latest.date)}`:'10 questions'}>
{latest?<><p>{advice(latest)}</p>{needsExam(latest)&&<ExamGuidance/>}<StepActions><Button onClick={()=>setSheet(true)}><ClipboardList size={16}/>Appointment sheet</Button><Button variant="outline" onClick={()=>setTab('progress')}><ChartNoAxesCombined size={16}/>See all results</Button><Button variant="outline" disabled={busy} onClick={()=>setDialog('check')}>New check-in</Button></StepActions></>:<><p>Ten quick questions about eyes, reading, and close work over the past week. Children can answer with an adult. The answers decide whether an eye examination is suggested and what to ask for.</p><StepActions><Button disabled={!ready||busy} onClick={()=>setDialog(p?'check':'profile')}>Start check-in<ArrowRight size={16}/></Button></StepActions></>}
</FlowStep>
<details className="more-activities"><summary><strong>More checks (optional)</strong><span>Screen-based vision checks that need a ruler and measured distance, and helper observations to bring to an eye-care visit.</span></summary><SuiteLibrary groups={['function','review']} records={data.suite.filter(r=>r.profileId===active)} disabled={!ready||busy} onStart={startSuite}/></details>
<p className="expanded-note">These games and questions are not clinically validated and have no age norms. They cannot diagnose an eye condition or explain a learning difficulty. Children should have adult help.</p>
</div></TabsContent>
<TabsContent value="practice"><div className="section-heading"><div><h2>A little practice, at your pace.</h2><p>These are skill activities, not proven treatments for visual or learning disorders.</p></div><label>Difficulty <select value={level} onChange={e=>setLevel(Number(e.target.value))}><option value={1}>Gentle</option><option value={2}>Steady</option><option value={3}>Challenge</option></select></label></div><ActivityLibrary mode="practice" level={level} disabled={!ready||busy} attempts={attempts} extendedAttempts={data.extended.filter(a=>a.profileId===active)} suiteRecords={data.suite.filter(a=>a.profileId===active)} onSuite={startSuite} onStart={kind=>start(kind,'practice')} onExtended={kind=>startExpanded(kind,'practice')} onPrint={setWorksheet}/><p className="mobile-warning">Use a laptop or tablet at least 700 pixels wide for screen activities. Printed activities remain available.</p><div className="information"><h3>Keep practice comfortable</h3><p>Choose one activity, then take a break and check how you feel. Difficulty changes the task, not a treatment dose. Stop for discomfort, blur, or double vision and seek eye-care advice for recurring symptoms.</p><p>The activities were originally designed for ages 8–12. People of other ages can use them, but difficulty is not tailored or validated by age. There are no clinical norms or established treatment benefits for these activities. <button className="text-link" onClick={()=>setTab('evidence')}>Read the evidence and limitations</button></p></div></TabsContent>
<TabsContent value="progress"><div className="section-heading"><div><h2>{p?`${p.nickname}’s progress`:'Your progress'}</h2><p>Compare results with earlier sessions from the same profile.</p></div><div className="heading-actions"><Button onClick={()=>setSheet(true)} disabled={!p}><ClipboardList size={16}/>Appointment sheet</Button><Button variant="outline" onClick={()=>window.print()} disabled={!p}><Printer size={16}/>Print full report</Button></div></div>{p?<><div className="report-profile">{p.nickname} · Age {p.age} · Glasses: {p.glasses}<p>Existing diagnoses (reported): {p.diagnoses||'None recorded'}</p><p>Observations: {p.observations||'None recorded'}</p></div><section className="information next-steps"><h3>Next steps: symptoms come before scores</h3><p>{advice(latest)}</p>{needsExam(latest)?<ExamGuidance onSheet={()=>setSheet(true)}/>:!latest&&<Button variant="outline" onClick={()=>setDialog('check')}>Start check-in</Button>}</section><div className="activity-grid">{kinds.map(kind=>{const list=attempts.filter(a=>a.kind===kind&&a.mode==='assessment'&&a.status==='complete');const last=list.at(-1);const first=last?list.find(a=>a.id!==last.id&&comparable(a,last)):undefined;return <section className="metric-card" key={kind}><h3>{labels[kind]}</h3><strong>{last?`${accuracy(last)}%`:'—'}</strong><p>{last?`${last.correct}/6 correct · ${last.seconds.toFixed(1)} seconds`:'No completed assessment yet'}</p>{first&&last?<p className="comparison">Earlier: {accuracy(first)}% · {first.seconds.toFixed(1)}s<br/>{date(first.date)} → {date(last.date)}</p>:<p className="subtle">Two completed assessments with matching task version, difficulty, and a single input method are needed for comparison. Mixed-input sessions are excluded.</p>}</section>})}</div><p className="information">A change in score is not proof of treatment benefit or recovery. Familiarity, attention, sleep, device size, and testing conditions can affect results. Time includes the memory display; compare only under similar conditions.</p><ExpandedProgress sessions={data.extended.filter(a=>a.profileId===active)}/><SuiteProgress records={data.suite.filter(r=>r.profileId===active)}/><h3>Check-ins</h3>{checks.length?checks.slice().reverse().map(c=><section className="history-check" key={c.id}><strong>{date(c.date)}</strong><dl>{symptoms.map((s,i)=>c.responses[i]&&<div key={s}><dt>{s}</dt><dd>{c.responses[i]}</dd></div>)}</dl><p>{c.observations||'No additional observations.'}</p></section>):<p className="empty-message">No check-ins yet. Answer the check-in in step 4 on Home.</p>}<h3>Session history</h3>{attempts.length?<div className="table-wrap"><table><thead><tr><th>Date</th><th>Activity</th><th>Mode / level</th><th>Result</th><th>Time</th><th>Input</th></tr></thead><tbody>{attempts.slice().reverse().map(a=><tr key={a.id}><td>{date(a.date)}</td><td>{labels[a.kind]}</td><td>{a.mode} / {a.difficulty}</td><td>{a.status==='complete'?`${a.correct}/6 correct`:'Incomplete · excluded'}</td><td>{a.status==='complete'?`${a.seconds.toFixed(1)}s`:'—'}</td><td>{a.input}</td></tr>)}</tbody></table></div>:<p className="empty-message">Your first completed activity will appear here.</p>}</>:<section className="empty-message">Create or choose a profile to see its history.</section>}</TabsContent>
<TabsContent value="evidence"><div className="section-heading"><div><h2>Useful tools. Clear limits.</h2><p>Evidence reviewed September 13, 2026 · Activities are not clinically validated for any age.</p></div></div><div className="evidence-grid"><section className="information"><h3>What is—and isn’t—being measured</h3><p>Visual search records target selection, visual memory records pattern recognition after a brief display, and spatial matching records pattern comparison. Accuracy and elapsed time describe only those tasks.</p><p>Other activities explore detailed shape search, mental rotation, sequential memory, pattern construction, and block assembly. Their assessments record 12 rounds with individual accuracy, responses, and times. These original activities and symptom questions have not been clinically validated. They have no diagnostic cutoffs, age percentiles, or giftedness-specific norms. They cannot measure eye alignment, focusing, convergence, or eye movements.</p><h3>Additional assessments and webcam estimates</h3><p>Additional tasks cover figure–ground, visual closure, form constancy, working memory, attention and comparison. Visual-function checks use custom symbols, RGB contrast and colour steps, and self-reported grid observations. They do not establish clinical acuity, contrast sensitivity, colour deficiency, or eye health. Camera tasks require local calibration and separate checks; failure means the measurement was unusable, not that an eye problem was found. Assisted observations document what a helper noticed without calculating an alignment angle or diagnosing convergence insufficiency.</p><p>Camera processing uses locally hosted MediaPipe face landmarks and a custom gaze mapping, with no clinical validation. Eye-tracking sessions retain no video or raw eye coordinates. Assisted observations optionally record silent video in temporary memory for an explicit private download; recordings are not included in backups. Camera quality thresholds are engineering choices. These modules are for adults and assisted children who understand the instructions; no age norms are available. Content reviewed September 22, 2026. Each module links its research context.</p><h3>Practice is not a treatment claim</h3><p>Evidence supports certain clinician-directed treatments for diagnosed convergence insufficiency. It does not establish that these browser activities treat that condition, dyslexia, or other learning difficulties. Clinical trials of convergence treatment have not shown improved standardized reading performance.</p><h3>When to seek help</h3><p>Recurring blurred or double vision, sore eyes, or persistent everyday difficulty warrant professional assessment regardless of game scores. Stop activities that cause symptoms. Sudden new double vision or sudden vision loss needs urgent medical attention; do not continue testing here.</p></section><div>{sources.map(([title,by,url])=><a className="source-card" href={url} target="_blank" rel="noreferrer" key={url}><BookOpen size={20}/><span><strong>{title}</strong><small>{by}</small></span><ArrowUpRight size={18}/></a>)}<section className="side-card"><h3>Your data stays here</h3><p>Profiles and history are saved in this browser’s IndexedDB. There are no accounts, ads, or app analytics. Browser data is not encrypted by this app; other people using this browser may access it.</p><p>Clearing site data or using private browsing may erase history. Export a backup to keep or move it. Backup files contain personal information—store them privately.</p></section></div></div></TabsContent>
</Tabs><footer><span><Eye size={18}/> little lens</span><p>A space for individual or shared curiosity and practice. Not a diagnostic or treatment service.</p><span>Children: use with adult help</span></footer></main>
<Dialog open={!!dialog} onOpenChange={v=>!v&&setDialog(null)}><DialogContent className="family-dialog"><DialogHeader><DialogTitle>{dialog==='profile'?'Create a profile':dialog==='check'?'Check-in':'Profiles & data'}</DialogTitle><DialogDescription>{dialog==='profile'?'Use a nickname. Everything stays in this browser.':dialog==='check'?'Original observation questions, not a validated clinical questionnaire.':'Back up, restore, or remove your local history.'}</DialogDescription></DialogHeader>{error&&<p role="alert" className="alert">{error}</p>}{dialog==='profile'&&<form onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const parsed=profileSchema.safeParse({id:crypto.randomUUID(),nickname:f.get('nickname'),age:Number(f.get('age')),glasses:f.get('glasses'),diagnoses:f.get('diagnoses'),observations:f.get('observations')});if(!parsed.success){setError("Enter a nickname and a whole-number age of 0 or more.");return;}if(await persist({...data,profiles:[...data.profiles,parsed.data]})){setActive(parsed.data.id);setDialog(null);}}}><label>Nickname<Input name="nickname" required maxLength={40} placeholder="e.g. Alex"/></label><div className="form-row"><label>Age (years)<Input name="age" type="number" inputMode="numeric" min={0} step={1} required placeholder="Enter age"/></label><label>Wears glasses<select name="glasses"><option>No</option><option>Yes</option><option>Sometimes</option></select></label></div><label>Existing diagnoses, if any<Textarea name="diagnoses" maxLength={2000} placeholder="Optional · reported"/></label><label>What have you noticed?<Textarea name="observations" maxLength={2000} placeholder="Optional · everyday experiences"/></label><p className="subtle">This app explores task performance. It cannot diagnose or rule out visual or learning conditions. The first eight activities were designed for ages 8–12; the wider library has varied demands. None are validated by age. Adults can use them independently; children should have adult help.</p><Button disabled={busy}>Create profile <ArrowRight size={16}/></Button></form>}{dialog==='check'&&p&&<form onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const c:Check={id:crypto.randomUUID(),profileId:p.id,date:new Date().toISOString(),responses:symptoms.map((_,i)=>f.get('s'+i) as Check['responses'][number]),observations:String(f.get('observations'))};if(await persist({...data,checks:[...data.checks,c]})){setDialog(null);setNotice(advice(c));}}}><p>Thinking about the past week, record your experiences. If assisting someone, ask what they noticed and add your observations.</p>{checkGroups.map(([title,items])=><fieldset className="symptom-group" key={title}><legend>{title}</legend>{items.map(i=><label className="symptom-row" key={i}>{symptoms[i]}<select name={'s'+i} required defaultValue=""><option value="" disabled>Choose frequency</option>{['Never','Sometimes','Often','Not sure'].map(x=><option key={x}>{x}</option>)}</select></label>)}</fieldset>)}<label>Everyday examples or changes<Textarea name="observations" maxLength={2000}/></label><Button disabled={busy}>Save check-in</Button></form>}{dialog==='settings'&&<div className="settings-content"><p>Anyone using this browser can view local profiles. Export before clearing browser data or switching devices.</p><Button variant="outline" onClick={()=>exportFile(data)}><Download/>Export all profiles</Button><Button variant="outline" disabled={!ready||busy} onClick={()=>file.current?.click()}><Upload/>Import backup (replaces local data)</Button><input ref={file} type="file" accept="application/json,.json" hidden onChange={e=>importBackup(e.target.files?.[0])}/><hr/>{p&&<Button variant="outline" disabled={busy} onClick={async()=>{if(confirm(`Delete ${p.nickname} and all their history? This cannot be undone.`)){if(await persist({...data,profiles:data.profiles.filter(x=>x.id!==p.id),checks:data.checks.filter(x=>x.profileId!==p.id),attempts:data.attempts.filter(x=>x.profileId!==p.id),extended:data.extended.filter(x=>x.profileId!==p.id),suite:data.suite.filter(x=>x.profileId!==p.id)})){setWebcamSkips(forgetWebcamSkips([p.id]));setActive('');}}}}>Delete {p.nickname}’s profile</Button>}<Button variant="destructive" disabled={!ready||busy} onClick={async()=>{if(confirm('Delete ALL profiles and history from this browser? This cannot be undone.')){if(await persist(structuredClone(empty))){setWebcamSkips(forgetWebcamSkips('all'));setActive('');setDialog(null);}}}}>Delete all local data</Button></div>}</DialogContent></Dialog>
{suiteRun&&<SuiteRunner key={suiteRun.id} initial={suiteRun} onSave={saveSuite} onClose={()=>{setSuiteRun(null);gameClosed('Review this session in Results.');}}/>}{expandedRun&&<ExpandedRunner key={expandedRun.id} initial={expandedRun} onSave={saveExpanded} onClose={()=>{setExpandedRun(null);gameClosed('Activity saved. Take a break, then review round-by-round results in Results.');}} error={error}/>}{run&&<Activity key={run.id} attempt={run} onFinish={finish} saving={busy} error={error}/>}{worksheet&&<Worksheet kind={worksheet} onClose={()=>setWorksheet(null)}/>}{upNext&&p&&flowMode&&!run&&!expandedRun&&!suiteRun&&<UpNext mode={flowMode} next={nextGame(data,p.id,flowMode==='games'?clickingGames:webcamGames,skipped)} progress={progress} score={score} onStart={play} onSkip={g=>setSkipped(new Set([...skipped,gameKey(g)]))} onContinue={()=>{if(flowMode==='games'&&!webcamSkipped){setFlowMode('webcam');setSkipped(new Set());}else{setUpNext(false);setFlowMode(null);setDialog('check');}}} onSkipWebcam={()=>{setWebcamSkipped(true);setUpNext(false);setFlowMode(null);setDialog('check');}} onClose={()=>{setUpNext(false);setFlowMode(null);}}/>}{sheet&&p&&<AppointmentSheet profile={p} checks={checks} data={data} onClose={()=>setSheet(false)}/>}</>;
}
function Activity({attempt,onFinish,saving,error}:{attempt:Attempt,onFinish:(a:Attempt)=>Promise<void>,saving:boolean,error:string}){const [phase,setPhase]=useState<'intro'|'demo'|'ready'|'show'|'answer'|'next'|'feedback'|'done'>('intro'),[demoPick,setDemoPick]=useState<number|null>(null),[round,setRound]=useState(0),[item,setItem]=useState<Item>(()=>makeItem(attempt.kind,attempt.difficulty)),[correct,setCorrect]=useState(0),[last,setLast]=useState(false),[result,setResult]=useState<Attempt|null>(null),[blocked,setBlocked]=useState(false);const started=useRef(0),elapsed=useRef(0),input=useRef<Attempt['input']>('unknown'),locked=useRef(false),answered=useRef(0);const assessment=attempt.mode==='assessment';
function mark(v:Attempt['input']){input.current=input.current==='unknown'?v:input.current===v?v:'mixed';}
function stop(){if(started.current){elapsed.current+=performance.now()-started.current;started.current=0;}const a={...attempt,correct,answered:answered.current,input:input.current,seconds:elapsed.current/1000,status:'incomplete' as const};setResult(a);setPhase('done');}
useEffect(()=>{const onHide=()=>{if(document.hidden&&['show','answer'].includes(phase))stop();};const resize=()=>{setBlocked(window.innerWidth<700);if(window.innerWidth<700&&['show','answer'].includes(phase))stop();};resize();document.addEventListener('visibilitychange',onHide);window.addEventListener('resize',resize);return()=>{document.removeEventListener('visibilitychange',onHide);window.removeEventListener('resize',resize);};},[phase,correct]);
useEffect(()=>{if(phase==='show'){const timer=setTimeout(()=>setPhase('answer'),3000);return()=>clearTimeout(timer);}if(phase==='next'){const timer=setTimeout(()=>document.hidden?setPhase('feedback'):begin(),700);return()=>clearTimeout(timer);}},[phase]);
function begin(){locked.current=false;setItem(makeItem(attempt.kind,attempt.difficulty));started.current=performance.now();setPhase(attempt.kind==='memory'?'show':'answer');}
function choose(i:number){if(locked.current)return;locked.current=true;elapsed.current+=performance.now()-started.current;started.current=0;answered.current=round+1;const hit=i===item.answer;const next=correct+(hit?1:0);setCorrect(next);setLast(hit);if(round===5){setResult({...attempt,correct:next,answered:6,input:input.current,seconds:elapsed.current/1000,status:'complete'});setPhase('done');}else{setRound(round+1);setPhase(assessment&&round!==2?'next':'feedback');}}
return <Dialog open onOpenChange={()=>{if(phase!=='done')stop();}}><DialogContent className="runner-dialog" showCloseButton={false} onPointerDownOutside={e=>e.preventDefault()} aria-describedby={undefined}><DialogTitle className="sr-only">{labels[attempt.kind]}</DialogTitle><div className="runner"><div className="runner-head"><span className="brand"><Eye/>{labels[attempt.kind]}</span><Button variant="outline" onClick={stop} disabled={phase==='done'}>Stop activity</Button></div><div className="runner-meta"><span>{assessment?'Assessment · consistent difficulty':`Practice · level ${attempt.difficulty}`}</span><span>{phase==='intro'||phase==='demo'?'Instructions · not timed':phase==='feedback'||phase==='next'?`${round} of 6 done`:`${Math.min(round+1,6)} of 6`}</span></div><div className="runner-body">{error&&<p role="alert" className="alert">{error}</p>}{blocked?<><h2>A little more screen space, please.</h2><p>Use a laptop or tablet at least 700 pixels wide for screen activities.</p><Button onClick={()=>onFinish(result||attempt)} disabled={saving}>Return to workspace</Button></>:<>{phase==='intro'&&<><span className="eyebrow">LET’S TRY IT</span><h2>{labels[attempt.kind]}</h2><p>{attempt.kind==='search'?'Find the diamond among the circles. Choose it with a click, tap, or by tabbing to it and pressing Enter.':attempt.kind==='memory'?'Look at the pattern for three seconds. When it disappears, choose the same pattern from four options.':'Look at the reference pattern. Choose the option with filled squares in exactly the same positions.'}</p><p>Six rounds{assessment?', with a short break halfway':''}. Work accurately at a comfortable pace. Stop for discomfort, blur, or double vision. Leaving the tab during a round ends the attempt as incomplete.</p><Button onClick={()=>setPhase('demo')}>Try one first <ArrowRight/></Button></>}{phase==='demo'&&<><h2>Try one first</h2>{attempt.kind==='search'?<><p>Which one is the diamond?</p><div className="demo-choices">{[0,0,1,0].map((d,i)=><button key={i} aria-label={`Example shape ${i+1}`} aria-pressed={demoPick===i} onClick={()=>setDemoPick(i)} className="demo-shapes">{d?'◇':'○'}</button>)}</div></>:<><p>{attempt.kind==='memory'?'Here is a pattern. Which option matches it? In the activity, the pattern disappears after three seconds before you choose.':'Here is a reference. Which option has filled squares in exactly the same places?'}</p><div className="demo-patterns"><div className="reference"><span>Pattern</span><Pattern cells={[0,4,8]} large/></div><div className="demo-choices">{[[2,4,6],[0,4,8]].map((cells,i)=><button key={i} aria-label={`Example option ${i+1}`} aria-pressed={demoPick===i} onClick={()=>setDemoPick(i)}><Pattern cells={cells}/></button>)}</div></div></>}<p role="status" className="demo-feedback">{demoPick===null?'Choose one to try it out.':demoPick===(attempt.kind==='search'?2:1)?'Yes, that’s the one! You’re ready.':attempt.kind==='search'?'Not quite. That one is a circle. Look for the shape with corners.':'Not quite. Look at which squares are filled, not just how many. Try again.'}</p><Button disabled={demoPick!==(attempt.kind==='search'?2:1)} onClick={()=>setPhase('ready')}>I’m ready <ArrowRight/></Button></>}{phase==='ready'&&<><h2>Ready when you are.</h2><p>The next button starts timing. Instructions and breaks do not count. Use the same input method throughout.</p><Button onClick={begin}>Begin six rounds <Play/></Button></>}{(phase==='show'||phase==='answer')&&<><h2>{phase==='show'?'Remember this pattern':attempt.kind==='search'?'Find the diamond':'Choose the matching pattern'}</h2>{phase==='show'?<Pattern cells={item.target} large/>:<>{attempt.kind==='spatial'&&<div className="reference"><span>Reference</span><Pattern cells={item.target} large/></div>}<div className={attempt.kind==='search'?'search-board':'options-board'} style={attempt.kind==='search'?{gridTemplateColumns:`repeat(${Math.sqrt(item.options.length)}, 1fr)`}:undefined}>{item.options.map((o,i)=><button key={i} aria-label={`Option ${i+1}`} onPointerDown={e=>mark(e.pointerType==='touch'?'touch':'mouse')} onKeyDown={e=>{if(e.key==='Enter'||e.key===' ')mark('keyboard');}} onClick={()=>choose(i)}>{attempt.kind==='search'?<span aria-hidden="true">{o[0]===1?'◇':'○'}</span>:<Pattern cells={o}/>}<small>{i+1}</small></button>)}</div></>}</>}{phase==='next'&&<><span className="eyebrow">ROUND {round+1} OF 6</span><h2>Here comes the next one…</h2></>}{phase==='feedback'&&<><span className="eyebrow">{assessment&&round===3?'HALFWAY':'ROUND SAVED'}</span><h2>{assessment?round===3?'Halfway there. Take a breath.':'Take a breath.':last?'That’s a match.':'Keep exploring.'}</h2><p>Rest your eyes if you need to. Start the next round when comfortable.</p><Button onClick={begin}>Next round <ArrowRight/></Button></>}{phase==='done'&&result&&<><span className="eyebrow">{result.status==='complete'?'ACTIVITY COMPLETE':'ACTIVITY STOPPED'}</span><h2>{result.status==='complete'?`${result.correct} of 6 correct`:'Time for a break.'}</h2>{result.status!=='complete'&&<p>This attempt stays incomplete and will not be used in comparisons.</p>}{result.status==='complete'&&<p className="result-meaning">{`Correct answers: ${result.correct} of 6 rounds. Answering time: ${result.seconds.toFixed(1)} seconds (instructions and breaks are not counted).`}</p>}<p>{result.status==='complete'?'The time is only for comparing with your own later sessions. This activity cannot check eye teaming or focusing up close, so if reading is hard or eyes get tired, an eye examination is still worthwhile.':'Check how you feel before deciding what to do next.'}</p><Button disabled={saving} onClick={()=>onFinish(result)}>{saving?'Saving…':'Save & return'}</Button></>}</>}</div><div className="runner-footer">Work at your pace · No countdown · Stop whenever you need</div></div></DialogContent></Dialog>;
}
function Worksheet({kind,onClose}:{kind:Kind,onClose:()=>void}){const [items]=useState(()=>Array.from({length:6},()=>makeItem(kind,2)));return <Dialog open onOpenChange={v=>!v&&onClose()}><DialogContent className="worksheet-overlay" showCloseButton={false} aria-describedby={undefined}><DialogTitle className="sr-only">Printable {labels[kind]} worksheet</DialogTitle><div className="worksheet"><div className="no-print worksheet-actions"><Button variant="outline" onClick={onClose}>Close worksheet</Button><Button onClick={()=>window.print()}><Printer/>Print worksheet</Button></div><h1>Little Lens / {labels[kind]}</h1><p>Skill practice · Children should have adult help · Not a clinical test or treatment.</p><p>{kind==='memory'?'Use a helper for this memory worksheet: they show the reference briefly, then cover it before you choose a match. Keep the page covered below the current question.':kind==='search'?'Circle the diamond in each group.':'Circle the pattern that exactly matches the reference.'} Work comfortably, take breaks, and stop for eye discomfort, blur, or double vision. Paper results are not compared with browser assessments.</p>{items.map((it,n)=><section className="worksheet-question" key={n}><h3>{n+1}.</h3>{kind!=='search'&&<div className="reference"><span>Reference</span><Pattern cells={it.target}/></div>}<div className={kind==='search'?'paper-search':'paper-options'}>{it.options.map((o,i)=><span key={i}>{kind==='search'?(o[0]?'◇':'○'):<><Pattern cells={o}/><small>{i+1}</small></>}</span>)}</div></section>)}<section className="answer-key"><h2>Answer key</h2><p>{items.map((it,n)=>`${n+1}: option ${it.answer+1}`).join(' · ')}</p><p>Search positions count left to right, row by row. Original, unvalidated practice materials. No clinical norms or established treatment benefit. Evidence reviewed September 13, 2026.</p><p>Learn more: nei.nih.gov/eye-health-information/eye-conditions-and-diseases/convergence-insufficiency</p></section></div></DialogContent></Dialog>}

const activityGroups: {title:string;items:(Kind|ExtendedKind|SuiteKind)[]}[] = [
 {title:'Search & discrimination',items:['search','detailSearch','figureGround','closure','constancy']},
 {title:'Memory',items:['memory','sequence','workingMemory']},
 {title:'Spatial skills',items:['spatial','rotation','pattern','blocks']},
 {title:'Attention & comparison',items:['selective','sustained','comparison']},
];
function ActivityLibrary({mode,level,disabled,attempts,extendedAttempts,suiteRecords,onSuite,onStart,onExtended,onPrint}:{mode:'assessment'|'practice';level:number;disabled:boolean;attempts:Attempt[];extendedAttempts:ExtendedAttempt[];suiteRecords:SuiteRecord[];onSuite:(kind:SuiteKind)=>void;onStart:(kind:Kind)=>void;onExtended:(kind:ExtendedKind)=>void;onPrint:(kind:Kind)=>void}) {
 return <section className="skill-library" aria-label="Activity library">
 {mode==='assessment'&&<div className="section-heading"><div><h2>Explore visual skills</h2><p>Choose an activity together. Instructions are untimed; take breaks between activities.</p><p>Assessment difficulty stays the same each time to support comparison.</p></div></div>}
 {activityGroups.filter(g=>mode==='assessment'||g.items.some(k=>!suiteKinds.includes(k as SuiteKind))).map(group=><section className="skill-group" key={group.title} aria-label={group.title}><h3 className="skill-group-title">{group.title}</h3><div className="skill-cards">{group.items.filter(k=>mode==='assessment'||!suiteKinds.includes(k as SuiteKind)).map(item=>{
 if(suiteKinds.includes(item as SuiteKind)){const k=item as SuiteKind;return <article className="expanded-card" key={k}><div className="expanded-card-icon"><Eye size={24}/></div><h3>{suiteCatalog[k].title}</h3><p>{suiteCatalog[k].description}</p><p className="activity-protocol">{trialCount(k)} rounds · Consistent task demands</p><Button className="expanded-launch" disabled={disabled} onClick={()=>onSuite(k)}>{suiteRecords.some(r=>r.kind===k&&r.status==='complete')?'Reassess skill':'Start assessment'}<ArrowUpRight size={16}/></Button></article>;}

 if(!kinds.includes(item as Kind))return <ExtendedActivityCard key={item} kind={item as ExtendedKind} mode={mode} level={level} disabled={disabled} completed={extendedAttempts.some(a=>a.kind===item&&a.mode==='assessment'&&a.status==='complete')} onStart={onExtended}/>;
 const kind=item as Kind, Icon=icons[kind], done=attempts.some(a=>a.kind===kind&&a.mode==='assessment'&&a.status==='complete');
 return <article className={`expanded-card skill-${kind}`} key={kind}><div className="expanded-card-icon"><Icon size={24}/></div><span className="skill-label">{kind==='search'?'Visual search':kind==='memory'?'Visual memory':'Pattern comparison'}</span><h3>{labels[kind]}</h3><p>{descriptions[kind]}</p><div className="expanded-card-example" aria-hidden="true">{kind==='search'?<span className="search-preview">○ ○ ○<br/>○ ◇ ○<br/>○ ○ ○</span>:<Pattern cells={kind==='memory'?[0,4,7]:[1,3,4,8]}/>}</div><p className="activity-protocol">{mode==='assessment'?'6 rounds · Consistent difficulty':`6 rounds · Level ${level}: ${level===1?'Gentle':level===2?'Steady':'Challenge'}`}</p><Button className="expanded-launch" disabled={disabled} onClick={()=>onStart(kind)}>{mode==='practice'?'Start activity':done?'Reassess skill':'Start assessment'}<ArrowUpRight size={16}/></Button>{mode==='practice'&&<Button variant="outline" onClick={()=>onPrint(kind)}><Printer size={16}/>Print activity</Button>}</article>;
 })}</div></section>)}
 <p className="expanded-note">The first eight activities were designed for ages 8–12; the wider library adds varied task demands. Adults and assisted children can participate; they are not age-normed or validated clinical tests or treatments. Children should have adult help. {mode==='assessment'?'Difficulty stays fixed. Progress compares completed assessments of the same activity with compatible settings; round counts are shown on each card.':'Choose a comfortable difficulty and stop whenever you need a break.'}</p>
 </section>;
}

function AppointmentSheet({profile,checks,data,onClose}:{profile:Profile;checks:Check[];data:Data;onClose:()=>void}){
 const recent=checks.slice(-3).reverse(),latest=checks.at(-1);
 const tried=new Map<string,{count:number;last:string}>();
 const add=(title:string,d:string)=>{const t=tried.get(title);tried.set(title,{count:(t?.count||0)+1,last:!t||d>t.last?d:t.last});};
 for(const a of data.attempts)if(a.profileId===profile.id&&a.status==='complete')add(labels[a.kind],a.date);
 for(const a of data.extended)if(a.profileId===profile.id&&a.status==='complete')add(extendedCatalog[a.kind].title,a.date);
 for(const r of data.suite)if(r.profileId===profile.id&&r.status==='complete')add(suiteCatalog[r.kind].title,r.date);
 return <Dialog open onOpenChange={v=>!v&&onClose()}><DialogContent className="worksheet-overlay" showCloseButton={false} aria-describedby={undefined}><DialogTitle className="sr-only">Appointment sheet for {profile.nickname}</DialogTitle><div className="worksheet appointment-sheet">
 <div className="no-print worksheet-actions"><Button variant="outline" onClick={onClose}>Close</Button><Button onClick={()=>window.print()}><Printer/>Print sheet</Button></div>
 <h1>Notes for an eye-care appointment</h1>
 <p className="sheet-meta"><strong>{profile.nickname}</strong> · Age {profile.age} · Wears glasses: {profile.glasses} · Prepared {date(new Date().toISOString())} with Little Lens</p>
 <h2>What we have noticed</h2><p>{profile.observations||'Nothing recorded in the profile.'}{latest?.observations?<><br/>Latest check-in ({date(latest.date)}): {latest.observations}</>:null}</p>
 {profile.diagnoses&&<p>Existing diagnoses (reported): {profile.diagnoses}</p>}
 <h2>How often, over the past week</h2>
 {recent.length?<table><thead><tr><th>Symptom</th>{recent.map(c=><th key={c.id}>{date(c.date)}</th>)}</tr></thead><tbody>{symptoms.map((s,i)=><tr key={s}><td>{s}</td>{recent.map(c=><td key={c.id}>{c.responses[i]||'Not asked'}</td>)}</tr>)}</tbody></table>:<p>No check-ins recorded yet.</p>}
 <h2>Questions to ask</h2><ul>{appointmentQuestions.map(q=><li key={q}>{q}</li>)}</ul>
 <h2>Activities tried at home</h2>
 {tried.size?<ul>{[...tried].map(([title,t])=><li key={title}>{title}: {t.count} completed, most recently {date(t.last)}</li>)}</ul>:<p>None completed yet.</p>}
 <p className="sheet-note">These are on-screen activities, not clinical tests. They have no age norms and cannot measure eye teaming, focusing, eye movements, or eye health. Check-in questions are original and not a validated questionnaire. Full results are in the Little Lens progress report.</p>
 </div></DialogContent></Dialog>;
}

function gameDescription(g:FlowGame){return g.family==='original'?descriptions[g.kind]:g.family==='extended'?extendedCatalog[g.kind].description:suiteCatalog[g.kind].description;}
const stepNames=['Profile','Games','Webcam','Check-in'];
function FlowBar({progress,score,name,onStep}:{progress:FlowProgress;score:{correct:number;total:number;percent:number};name?:string;onStep:(step:number)=>void}){
 const percent=Math.round(progress.done/progress.total*100);
 return <div className="flow-bar" role="region" aria-label="Your progress"><ol className="flow-steps">{stepNames.map((label,i)=>{const n=i+1,state=progress.step>n?'done':progress.step===n?'current':'upcoming';return <li key={label} data-state={state}><button onClick={()=>onStep(n)} aria-current={state==='current'?'step':undefined}><span>{state==='done'?<CheckCircle2 size={14}/>:n}</span>{label}</button></li>;})}</ol>
 <div className="flow-meter"><div className="flow-track" role="progressbar" aria-label="Steps completed" aria-valuemin={0} aria-valuemax={progress.total} aria-valuenow={progress.done}><i style={{width:`${percent}%`}}/></div><small>{progress.step>4?'All steps done':`${progress.done} of ${progress.total} done`}{name?` · ${name}`:''}</small></div>
 <div className="flow-score" aria-label="Score"><Trophy size={16}/><span>{score.total?<><strong>{score.correct}/{score.total}</strong> correct · {score.percent}%</>:'No score yet'}</span></div></div>;
}
function FlowStep({n,id,title,icon,state,summary,children}:{n:number;id:string;title:string;icon:React.ReactNode;state:'done'|'current'|'upcoming';summary?:string;children:React.ReactNode}){
 return <section className="flow-step" id={id} data-state={state} aria-labelledby={`${id}-title`}><header><span className="flow-step-mark">{state==='done'?<CheckCircle2 size={20}/>:icon}</span><div><small>Step {n} of 4</small><h2 id={`${id}-title`}>{title}</h2></div>{summary&&<span className="flow-step-summary">{summary}</span>}</header><div className="flow-step-body">{children}</div></section>;
}
function StepActions({mobile,children}:{mobile?:string;children:React.ReactNode}){return <div className="step-actions"><div className={mobile?'game-play':''}>{children}</div>{mobile&&<p className="mobile-only subtle">{mobile}</p>}</div>}
function GameRow({game,status,disabled,onPlay}:{game:FlowGame;status:{played:boolean;score?:{correct:number;total:number}};disabled:boolean;onPlay:()=>void}){
 return <li className="game-row" data-played={status.played}><span className="game-status">{status.played?<CheckCircle2 size={18}/>:<i/>}</span><div><strong>{gameTitle(game)}</strong><small>{gameDescription(game)}</small></div><span className="game-score">{status.score?`${status.score.correct}/${status.score.total}`:status.played?'Played':'Not played'}</span><Button className="game-play" size="sm" variant={status.played?'outline':'default'} disabled={disabled} onClick={onPlay}>{status.played?'Replay':'Play'}</Button></li>;
}
function UpNext({mode,next,progress,score,onStart,onSkip,onContinue,onSkipWebcam,onClose}:{mode:'games'|'webcam';next?:FlowGame;progress:FlowProgress;score:{correct:number;total:number;percent:number};onStart:(g:FlowGame)=>void;onSkip:(g:FlowGame)=>void;onContinue:()=>void;onSkipWebcam:()=>void;onClose:()=>void}){
 const list=mode==='games'?clickingGames:webcamGames,played=mode==='games'?progress.games:progress.webcam;
 return <Dialog open onOpenChange={v=>!v&&onClose()}><DialogContent className="family-dialog up-next" aria-describedby={undefined}>
 {next?<><span className="eyebrow">{mode==='games'?'STEP 2 · GAMES':'STEP 3 · WEBCAM GAMES'} · {played} OF {list.length} PLAYED</span><DialogTitle>Next up: {gameTitle(next)}</DialogTitle><p>{gameDescription(next)}</p>{mode==='games'&&score.total>0&&<p className="up-next-score"><Trophy size={16}/>Score so far: {score.correct}/{score.total} correct · {score.percent}%</p>}<p className="subtle">Take a short break first if your eyes feel tired.</p><div className="step-actions"><Button onClick={()=>onStart(next)}><Play size={16}/>Start {gameTitle(next)}</Button><Button variant="outline" onClick={()=>onSkip(next)}><SkipForward size={16}/>Skip this one</Button><Button variant="ghost" onClick={onClose}>Take a break</Button></div></>
 :<><span className="eyebrow">{mode==='games'?'STEP 2 DONE':'STEP 3 DONE'}</span><DialogTitle>{played===list.length?`All ${list.length} ${mode==='games'?'games':'webcam games'} played!`:'No more games in this step'}</DialogTitle>{mode==='games'&&score.total>0&&<p className="up-next-score"><Trophy size={16}/>Score: {score.correct}/{score.total} correct · {score.percent}%</p>}{played<list.length&&<p>Skipped games stay on the home page to play later.</p>}<p>{mode==='games'?'Next: the experimental webcam games, or skip them and go straight to the check-in.':'Last step: ten quick check-in questions.'}</p><div className="step-actions"><Button onClick={onContinue}>{mode==='games'?'Continue to webcam games':'Start check-in'}<ArrowRight size={16}/></Button>{mode==='games'&&<Button variant="outline" onClick={onSkipWebcam}><SkipForward size={16}/>Skip to check-in</Button>}<Button variant="ghost" onClick={onClose}>Back to home</Button></div></>}
 </DialogContent></Dialog>;
}
